import{_ as t,o as n,c as r,a3 as s}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Tablet-Test: Ergebnis und Prüfablauf","description":"","frontmatter":{},"headers":[],"relativePath":"projects/atlas/tablet-test.md","filePath":"projects/atlas/tablet-test.md","lastUpdated":1793198184000}'),a={name:"projects/atlas/tablet-test.md"};function i(l,e,d,u,o,p){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="tablet-test-ergebnis-und-prufablauf" tabindex="-1">Tablet-Test: Ergebnis und Prüfablauf <a class="header-anchor" href="#tablet-test-ergebnis-und-prufablauf" aria-label="Permalink to &quot;Tablet-Test: Ergebnis und Prüfablauf&quot;">​</a></h1><p>Ebenfalls abgeschlossen: <a href="./tablet-uix-dauertest">60-Minuten-Dauertest mit UIX</a> auf beiden Hosts.</p><p>2026-10-19 · App 0.1.327 · HA 2026.10.2 · <code>192.168.178.177</code> / <code>192.168.178.68</code>.</p><p>Der Nutzer bestätigt 12 und 360 Karten sowie <strong>720 Karten auf beiden Hosts</strong> samt Theme-Wechsel und Wiederverbindung.</p><p>Samsung Galaxy Tab A6, Android 11 / LineageOS, Chrome Mobile 155. Nach Stoppen anderer Apps reagiert der Browser nach Nutzerrückmeldung flüssig. Stream Deck bleibt unverändert.</p><p>Funktionale Nutzerrückmeldung, keine FPS-/Speicher- oder Langzeitmessung. Separate detaillierte Hoch-/Querformatresultate wurden nicht gemeldet. Card-Mod 4.2.1 allein mit Bubble 3.4.2 und Mushroom 5.2.3; UIX wurde in dieser ersten Stufe nicht geprüft; der spätere Dauertest ist oben verlinkt.</p><p>Frische Vollbackups vor dem Test. Eigene Dashboards, Ressourcen und Zustände sind entfernt; WWW-Dateien im wiederherstellbaren File-Studio-Papierkorb. Alte Testlinks sind entfernt und keine aktiven Einstiegsseiten.</p><p>Alle sieben Projekte und sechs Plugins je Host sowie 531 erfasste Bestandsdateien auf .177 und neun auf .68 bleiben erhalten, einschließlich ursprünglicher Theme-Einstellungen und alter Papierkorbeinträge. Je drei neueste Vollbackups bleiben; PC-Sicherungen erhalten.</p><p>Für spätere Prüfungen zuerst einen leichten Browsercheck, dann 12, 360 und 720 Karten verwenden. Nur bei flüssiger Bedienung steigern; Hoch-/Querformat, Scrollen, synthetische Zustände, Themes und Wiederverbindung ohne Neuladen prüfen. Ursprüngliches Theme wiederherstellen. Eigene Dashboards ohne Admin-only und sichtbar in der Seitenleiste erstellen. Card-Mod und UIX niemals parallel laden.</p><p>Der spätere UIX-Stundenlauf ist abgeschlossen. Weiterhin offen sind unabhängige Messungen der Darstellungszeit und des Speicherverlaufs.</p>',10)])])}const h=t(a,[["render",i]]);export{c as __pageData,h as default};
